"""Chantier 2 (2026-11-01) — niveau 4 (« problème à plusieurs étapes ») de la
Quatrième.

58 notions n'avaient que 2 ou 3 exercices de niveau 4 dans le pool servi
(banque curée + banque générée) : on les porte à 4, sans toucher à l'échelle
1 à 4 de la banque (pas de niveau 5 en Quatrième). Ce module couvre les
chapitres rédigés dans tools/quatrieme/banque_chNN.py ; le chapitre 8 est
complété directement dans tools/build_quatrieme_bank.py.

La notion de chaque exercice est déduite de son identifiant (bloc
40 000 + 1 000 × chapitre + 100 × rang de la notion), après le dernier
identifiant déjà utilisé dans ce bloc. Chaque valeur annoncée est recalculée
par `verify` (Fraction, math, énumération exhaustive), indépendamment du
texte. Aucun exercice existant n'est modifié.
"""
import importlib
import math
from fractions import Fraction as F

from quatrieme.banque_commun import E, S, ID_BASE


def _ok(cond):
    return lambda: None if cond else "valeur fausse"


def _notion(ex_id):
    ch, k = (ex_id - ID_BASE) // 1000, (ex_id - ID_BASE) % 1000 // 100
    return getattr(importlib.import_module(f"quatrieme.cours_ch{ch:02d}"), f"N{k}")


# Relecture pédagogique (2026-11-01) : exercices d'application directe d'une
# seule méthode, d'abord placés au niveau 4, ramenés au niveau 3 (le niveau 4
# de la Quatrième est réservé aux problèmes à plusieurs étapes).
RAMENES_AU_NIVEAU_3 = {
    42220, 45218, 45120, 46318, 47119, 47318, 49218, 51122, 51123, 52123, 53218,
    53118, 55220, 56121, 57219, 57118, 57119, 57418, 50118, 54418, 54119, 53219,
}


def _q(ex_id, enonce, answer, hint, steps, checks=(), verify=None, difficulty=4):
    if ex_id in RAMENES_AU_NIVEAU_3:
        difficulty = 3
    return E(ex_id, _notion(ex_id), difficulty, enonce, answer, hint, S(*steps), checks=checks, verify=verify)


def _deg(x):
    return math.degrees(math.acos(x))


def _signe_neg(x):
    return (x - 1) * (x + 2) * (x - 3) < 0


